import {useCreateTask} from '@github-ui/agent-sessions/hooks/useCreateTask'
import type {AiFileFindings} from '../types/ai-findings'
import {generateAiFindingsFixPrompt} from '../utils/ai-findings-fix-prompt-generation'

type CreatePrOptions = {
  owner: string
  repo: string
  branch: string
}

export function useCreatePr({owner, repo, branch}: CreatePrOptions) {
  const {createTask} = useCreateTask({})

  const createPrForFile = (fileFindings: AiFileFindings) => {
    createTask({
      nwo: `${owner}/${repo}`,
      problemStatement: generateAiFindingsFixPrompt([fileFindings]),
      baseRef: branch,
      eventType: 'agents_page',
    })
  }

  return {
    createPrForFile,
  }
}
