import {useAnalytics} from '@github-ui/use-analytics'
import {Button} from '@primer/react'

export function AddToExistingBatch() {
  const {sendAnalyticsEvent} = useAnalytics()

  const handleOnClick = () => {
    sendAnalyticsEvent('comments.add_suggested_change_to_batch', 'ADD_SUGGESTED_CHANGE_TO_BATCH_BUTTON')
    // TODO: Implement when we add suggested changes batching
    // addSuggestedChangeToPendingBatch(suggestedChange)
  }
  return (
    <div className="d-flex flex-row-reverse">
      <Button variant="primary" onClick={handleOnClick}>
        Add suggestion to batch
      </Button>
    </div>
  )
}

try{ AddToExistingBatch.displayName ||= 'AddToExistingBatch' } catch {}