import {useCallback, useState} from 'react'
import type {AiFileFindings, AiFinding} from '../types/ai-findings'
import {blobPath} from '@github-ui/paths'
import {useCreatePr} from '../hooks/use-create-pr'
import {clsx} from 'clsx'

import styles from './RecentActivityFindingsFile.module.css'
import {ChevronDownIcon, ChevronRightIcon} from '@primer/octicons-react'
import {BranchName, Checkbox, CounterLabel, FormControl, Label, Link, RelativeTime} from '@primer/react'
import {SuggestedFixDiff} from './SuggestedFixDiff'

export type RecentActivityFindingsFileProps = {
  owner: string
  repo: string
  branch: string
  file: AiFileFindings
  hasNewFindings: boolean
  selected: boolean
  anyFilesSelected: boolean
  onSelectionChange: (selected: boolean) => void
}

export function RecentActivityFindingsFile({
  owner,
  repo,
  branch,
  file,
  hasNewFindings,
  selected,
  anyFilesSelected,
  onSelectionChange,
}: RecentActivityFindingsFileProps) {
  const [expanded, setExpanded] = useState(true)
  const fileLinkHref = blobPath({
    owner,
    repo,
    commitish: file.commitOid,
    filePath: file.filePath,
  })

  const {createPrForFile} = useCreatePr({owner, repo, branch})

  const onFixWithCopilotClick = useCallback(() => {
    createPrForFile(file)
  }, [createPrForFile, file])

  return (
    <>
      <div className={clsx(styles.fileHeader, 'Box-row')}>
        <FormControl>
          <Checkbox checked={selected} onChange={() => onSelectionChange(!selected)} />
          <FormControl.Label visuallyHidden>Select file: {file.filePath}</FormControl.Label>
        </FormControl>
        <button
          onClick={() => setExpanded(v => !v)}
          className="Button Button--iconOnly Button--invisible"
          aria-label={expanded ? `Collapse file: ${file.filePath}` : `Expand file: ${file.filePath}`}
        >
          {expanded ? <ChevronDownIcon /> : <ChevronRightIcon />}
        </button>
        <Link className={styles.fileLink} href={fileLinkHref}>
          <code>{file.filePath}</code>
        </Link>
        <CounterLabel>{file.findings.length}</CounterLabel>
        {hasNewFindings && (
          <span>
            <Label variant="accent">New</Label>
          </span>
        )}
        <div className={styles.fileMetadata}>
          Last push <RelativeTime date={new Date(file.lastPushAt)} /> to <BranchName as="span">{branch}</BranchName>
        </div>
        <div className={styles.fixWithCopilot}>
          {!anyFilesSelected && (
            <button onClick={onFixWithCopilotClick} className="Button Button--invisible" aria-label="Fix with Copilot">
              Fix with Copilot
            </button>
          )}
        </div>
      </div>
      {expanded &&
        file.findings.map(finding => {
          const key = `${file.filePath}:${finding.message}:${finding.startLine}:${finding.startColumn}`
          return <Finding key={key} finding={finding} filePath={file.filePath} />
        })}
    </>
  )
}

function Finding({finding, filePath}: {finding: AiFinding; filePath: string}) {
  return (
    <>
      <div className="Box-row px-0 pt-0 pb-1">
        <div className="px-3 py-2">{finding.message}</div>
        <SuggestedFixDiff
          fixFiles={finding.fixFiles}
          filePath={filePath}
          startLine={finding.startLine}
          endLine={finding.endLine}
          startColumn={finding.startColumn}
          endColumn={finding.endColumn}
          borderVariant="none"
        />
      </div>
    </>
  )
}

try{ RecentActivityFindingsFile.displayName ||= 'RecentActivityFindingsFile' } catch {}
try{ Finding.displayName ||= 'Finding' } catch {}