import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {repoCodeQualityRecentActivityRoute} from './repo-code-quality-recent-activity-route'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {Heading} from '@primer/react'
import {RecentActivityFindings} from '../components/RecentActivityFindings'

export function RepoCodeQualityRecentActivity() {
  const payload = useRouteQuery(repoCodeQualityRecentActivityRoute, 'mainQuery')
  const {owner, repo, defaultBranch, fileFindings} = payload.data

  return (
    <>
      <div className="d-flex flex-items-center gap-2">
        <Heading as="h2">Code quality — Recent activity</Heading>
        <BetaLabel feedbackUrl="https://docs.google.com/forms/d/e/1FAIpQLSfneUvxZ_qoaKuUHsvRQM-xFLG559yhxVAD8dQ876dIzTkWSw/viewform" />
      </div>
      <p>Recent activity shows Copilot-driven findings to improve your code in recent files that were changed.</p>
      <RecentActivityFindings owner={owner} repo={repo} branch={defaultBranch} initialFiles={fileFindings} />
    </>
  )
}

try{ RepoCodeQualityRecentActivity.displayName ||= 'RepoCodeQualityRecentActivity' } catch {}