import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import type {RepoCodeQualitySettingsResponse} from '../routes/repo-code-quality-settings-route'
import {fetchJson} from '../utils/fetch-json'

export function useToggleCodeQualityMutation(): UseMutationResult<RepoCodeQualitySettingsResponse, Error, boolean> {
  return useMutation({
    mutationFn: async (enabled: boolean) => {
      const response = await fetchJson<RepoCodeQualitySettingsResponse>(window.location.href, {
        method: 'POST',
        body: {enabled},
      })
      return response
    },
  })
}
